fn gcd_calc(m: u32, n: u32) -> u32 {
    // Inputs are assumed strictly positive as per the problem statement.
    let mut a = m;
    let mut b = n;

    // Euclidean algorithm (mod-based), keeping both values positive.
    // Invariant: gcd(a, b) == gcd(m, n)
    while a != b {
        if a > b {
            // Here b > 0, so a % b is well-defined and < b.
            let r = a % b;
            // Ensure positivity: if remainder is 0, gcd is b.
            if r == 0 {
                return b;
            }
            a = r;
        } else {
            let r = b % a;
            if r == 0 {
                return a;
            }
            b = r;
        }
        // Termination measure: a + b strictly decreases each iteration,
        // because one of them is replaced by a positive remainder < the other.
    }

    a
}